        System.out.println(zeichen + " " + name);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        var pfad = java.nio.file.Path.of("punktestand-demo.txt");
        int punkte = 35;
        java.nio.file.Files.writeString(pfad, Integer.toString(punkte), java.nio.charset.StandardCharsets.UTF_8);
        String text = java.nio.file.Files.readString(pfad, java.nio.charset.StandardCharsets.UTF_8);
        int geladen = Integer.parseInt(text.strip());
        System.out.println("Geladen: " + geladen);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        String base = args.length == 0 ? "http://127.0.0.1:8080" : args[0];
        var client = java.net.http.HttpClient.newBuilder()
            .connectTimeout(java.time.Duration.ofSeconds(3)).build();
        var request = java.net.http.HttpRequest.newBuilder(java.net.URI.create(base + "/sum?a=2&b=3"))
            .timeout(java.time.Duration.ofSeconds(3)).GET().build();
        try {
            var response = client.send(request, java.net.http.HttpResponse.BodyHandlers.ofString(java.nio.charset.StandardCharsets.UTF_8));
            if (response.statusCode() != 200) {
                System.out.println("Serverfehler: " + response.statusCode());
            } else {
                System.out.println("Ergebnis: " + response.body().strip());
            }
        } catch (java.io.IOException e) {
            System.out.println("Verbindung fehlgeschlagen");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.out.println("Anfrage unterbrochen");
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        var namen = java.util.List.of("Ada", "Alan", "Bo");
        String suche = "  al  ".strip().toLowerCase(java.util.Locale.ROOT);
        var treffer = namen.stream()
            .filter(name -> name.toLowerCase(java.util.Locale.ROOT).contains(suche))
            .toList();
        System.out.println(treffer);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        String eingabeA = "1.25", eingabeB = "4.25";
        try {
            var a = new java.math.BigDecimal(eingabeA.strip());
            var b = new java.math.BigDecimal(eingabeB.strip());
            System.out.println(a.add(b).toPlainString());
        } catch (NumberFormatException e) {
            System.out.println("Ungültige Zahl");
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        var preis = new java.math.BigDecimal("2.50");
        int menge = 3;
        var grundbetrag = preis.multiply(java.math.BigDecimal.valueOf(menge));
        var gesamt = grundbetrag.multiply(new java.math.BigDecimal("0.90"))
            .setScale(2, java.math.RoundingMode.HALF_UP);
        System.out.println(gesamt.toPlainString());
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        record Nachricht(long id, String sender, String text) {}
        var m = new Nachricht(1, "Ada", "Hallo");
        String paket = "sender=" + java.net.URLEncoder.encode(m.sender(), java.nio.charset.StandardCharsets.UTF_8)
            + "&text=" + java.net.URLEncoder.encode(m.text(), java.nio.charset.StandardCharsets.UTF_8);
        System.out.println(m.sender() + ": " + m.text());
        System.out.println(paket);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        String text = "Hallo";
        var history = new java.util.ArrayDeque<String>();
        history.push(text); text = "Hallo Java";
        history.push(text); text = "Hallo Java!";
        if (!history.isEmpty()) text = history.pop();
        System.out.println(text);
        if (!history.isEmpty()) text = history.pop();
        System.out.println(text);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        class Cache extends java.util.LinkedHashMap<String,Integer> {
            Cache() { super(16, 0.75f, true); }
            protected boolean removeEldestEntry(java.util.Map.Entry<String,Integer> entry) { return size() > 2; }
        }
        var cache = new Cache();
        cache.put("A", 10); cache.put("B", 20);
        cache.get("A");
        cache.put("C", 30);
        System.out.println(cache.keySet());
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        var stats = java.util.stream.IntStream.of(10, 20, 30).summaryStatistics();
        System.out.println("Anzahl: " + stats.getCount());
        System.out.println("Summe: " + stats.getSum());
        System.out.println("Durchschnitt: " + stats.getAverage());
    }
}
